BEGIN;
CREATE TABLE IF NOT EXISTS recovery_agent_retrieval_shadow_experiments(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),company_id uuid NOT NULL REFERENCES companies(id) ON DELETE CASCADE,proposal_id uuid NOT NULL REFERENCES recovery_agent_retrieval_change_proposals(id),scope varchar(32) NOT NULL DEFAULT 'recovery',status varchar(16) NOT NULL DEFAULT 'active' CHECK(status IN ('active','stopped')),sample_rate integer NOT NULL CHECK(sample_rate BETWEEN 1 AND 100),max_tokens_per_run integer NOT NULL CHECK(max_tokens_per_run BETWEEN 1 AND 10000),max_duration_ms integer NOT NULL CHECK(max_duration_ms BETWEEN 100 AND 20000),starts_at timestamptz NOT NULL,ends_at timestamptz NOT NULL CHECK(ends_at>starts_at),reason text NOT NULL CHECK(char_length(reason) BETWEEN 3 AND 500),created_by uuid NOT NULL,created_at timestamptz NOT NULL DEFAULT now(),stopped_by uuid,stopped_at timestamptz,stop_reason text CHECK(stop_reason IS NULL OR char_length(stop_reason) BETWEEN 3 AND 500));
CREATE INDEX IF NOT EXISTS recovery_retrieval_shadow_experiments_company_scope_idx ON recovery_agent_retrieval_shadow_experiments(company_id,scope,created_at DESC);
CREATE UNIQUE INDEX IF NOT EXISTS recovery_retrieval_shadow_experiments_active_uq ON recovery_agent_retrieval_shadow_experiments(company_id,scope) WHERE status='active';
ALTER TABLE recovery_agent_retrieval_shadow_experiments ENABLE ROW LEVEL SECURITY;
COMMIT;
